module secret_message (\n    input clk,\n    input rst_n,\n    input start,\n    input [4:0] arr_0, arr_1, arr_2, arr_3, arr_4, arr_5, arr_6, arr_7,\n    input [4:0] arr_8, arr_9, arr_10, arr_11, arr_12, arr_13, arr_14, arr_15,\n    input [3:0] len,\n    output reg [7:0] result,\n    output reg done\n);\n\n    localparam [2:0] IDLE = 3'd0;\n    localparam [2:0] PROCESS_CHAR = 3'd1;\n    localparam [2:0] UPDATE_E = 3'd2;\n    localparam [2:0] UPDATE_HIST = 3'd3;\n    localparam [2:0] UPDATE_MAX_START = 3'd4;\n    localparam [2:0] UPDATE_MAX_HIST = 3'd5;\n    localparam [2:0] UPDATE_MAX_E = 3'd6;\n    localparam [2:0] UPDATE_RESULT = 3'd7;\n\n    reg [2:0] state;\n    reg [3:0] index;\n    reg [4:0] k;\n    reg [4:0] current_char_reg;\n    reg [7:0] hist [0:25];\n    reg [7:0] e [0:25][0:25];\n    reg [7:0] max_d;\n    reg [7:0] max_e;\n    reg [4:0] i;\n    reg [4:0] j;\n    reg [5:0] idx_hist;\n\n    wire [4:0] current_char;\n    assign current_char = \n        (index ==  0) ? arr_0  :\n        (index ==  1) ? arr_1  :\n        (index ==  2) ? arr_2  :\n        (index ==  3) ? arr_3  :\n        (index ==  4) ? arr_4  :\n        (index ==  5) ? arr_5  :\n        (index ==  6) ? arr_6  :\n        (index ==  7) ? arr_7  :\n        (index ==  8) ? arr_8  :\n        (index ==  9) ? arr_9  :\n        (index == 10) ? arr_10 :\n        (index == 11) ? arr_11 :\n        (index == 12) ? arr_12 :\n        (index == 13) ? arr_13 :\n        (index == 14) ? arr_14 :\n        (index == 15) ? arr_15 : 5'd0;\n\n    integer idx, jdx;\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            done <= 1'b0;\n            result <= 8'd0;\n            index <= 4'd0;\n            k <= 5'd0;\n            current_char_reg <= 5'd0;\n            max_d <= 8'd0;\n            max_e <= 8'd0;\n            i <= 5'd0;\n            j <= 5'd0;\n            idx_hist <= 6'd0;\n            for (idx = 0; idx < 26; idx = idx + 1) begin\n                hist[idx] <= 8'd0;\n                for (jdx = 0; jdx < 26; jdx = jdx + 1) begin\n                    e[idx][jdx] <= 8'd0;\n                end\n            end\n        end else begin\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    if (start) begin\n                        state <= PROCESS_CHAR;\n                        index <= 4'd0;\n                        k <= 5'd0;\n                    end\n                end\n\n                PROCESS_CHAR: begin\n                    if (index < len) begin\n                        current_char_reg <= current_char;\n                        state <= UPDATE_E;\n                        k <= 5'd0;\n                    end else begin\n                        state <= UPDATE_MAX_START;\n                    end\n                end\n\n                UPDATE_E: begin\n                    e[k][current_char_reg] <= e[k][current_char_reg] + hist[k];\n                    k <= k + 5'd1;\n                    if (k == 5'd25) begin\n                        state <= UPDATE_HIST;\n                    end\n                end\n\n                UPDATE_HIST: begin\n                    hist[current_char_reg] <= hist[current_char_reg] + 8'd1;\n                    index <= index + 4'd1;\n                    state <= PROCESS_CHAR;\n                end\n\n                UPDATE_MAX_START: begin\n                    max_d <= 8'd0;\n                    max_e <= 8'd0;\n                    idx_hist <= 6'd0;\n                    state <= UPDATE_MAX_HIST;\n                end\n\n                UPDATE_MAX_HIST: begin\n                    if (idx_hist < 6'd26) begin\n                        if (hist[idx_hist] > max_d)\n                            max_d <= hist[idx_hist];\n                        idx_hist <= idx_hist + 6'd1;\n                    end else begin\n                        i <= 5'd0;\n                        j <= 5'd0;\n                        state <= UPDATE_MAX_E;\n                    end\n                end\n\n                UPDATE_MAX_E: begin\n                    if (i < 5'd26) begin\n                        if (j < 5'd26) begin\n                            if (e[i][j] > max_e)\n                                max_e <= e[i][j];\n                            j <= j + 5'd1;\n                        end else begin\n                            j <= 5'd0;\n                            i <= i + 5'd1;\n                        end\n                    end else begin\n                        state <= UPDATE_RESULT;\n                    end\n                end\n\n                UPDATE_RESULT: begin\n                    result <= (max_d > max_e) ? max_d : max_e;\n                    done <= 1'b1;\n                    state <= IDLE;\n                end\n\n                default: state <= IDLE;\n            endcase\n        end\n    end\nendmodule